<template>
  <section class="ai-models"><div class="catalog-heading"><div><p class="eyebrow">AI 问答管理 · 店主专用</p><h1>模型配置</h1><p class="muted">保存生成新版本草稿。测试通过后激活，新配置只供新请求使用。</p></div><button type="button" class="secondary-button" :disabled="busy" @click="reset">＋ 新建配置</button></div><PageStatus :loading="loading" :error="error" @retry="load" />
    <div class="model-layout"><aside><p v-if="!models.length" class="muted">尚未配置在线模型。基础咨询仍可使用。</p><button v-for="model in models" :key="model.id" type="button" class="model-version" :class="{ selected: selected?.id === model.id }" :disabled="busy" @click="choose(model)"><strong>{{ model.name }} <span v-if="model.active">当前激活</span></strong><small>{{ model.chatModel }} · v{{ model.id }}</small><small>{{ model.hasChatKey ? '生成Key已配置' : '无生成Key' }} · {{ model.hasEmbeddingKey ? '向量Key已配置' : '无向量Key' }}</small></button></aside>
      <section class="editor-section"><p v-if="selected && !selected.encryptionReady" class="ai-config-warning">部署主密钥未配置。保存Key前需在本机环境设置32字节Base64格式的 AI_CONFIG_ENCRYPTION_KEY。</p><p class="field-hint">推荐百炼中国内地工作空间：qwen3.7-plus 与 text-embedding-v4（1024维）。地址以控制台实际 OpenAI 兼容根地址为准。</p><p v-if="formError" class="form-message-error" role="alert">{{ formError }}</p><p v-if="notice" class="ai-success" role="status">{{ notice }}</p>
        <form @submit.prevent="save"><div class="address-fields"><label class="form-field address-field-wide">配置名称<input v-model.trim="form.name" required maxlength="100" placeholder="例如：百炼中文客服"></label><label class="form-field address-field-wide">生成接口根地址<input v-model.trim="form.chatBaseUrl" maxlength="500" type="url" placeholder="https://工作空间.cn-beijing.maas.aliyuncs.com/compatible-mode/v1"></label><label class="form-field">生成模型<input v-model.trim="form.chatModel" required maxlength="100"></label><label class="form-field">生成API Key<input v-model="chatKey" type="password" autocomplete="new-password" maxlength="500" :placeholder="selected?.hasChatKey ? '已配置，留空保留' : '填写新的Key'"><span class="field-hint">{{ selected?.hasChatKey ? '已配置 ••••••••' : '尚未配置' }}</span></label><label class="checkbox-field address-field-wide"><input v-model="form.clearChatKey" type="checkbox">明确清除新草稿的生成Key</label><label class="form-field address-field-wide">向量接口根地址<input v-model.trim="form.embeddingBaseUrl" maxlength="500" type="url" placeholder="填写向量服务的OpenAI兼容根地址"></label><label class="form-field">向量模型<input v-model.trim="form.embeddingModel" maxlength="100"></label><label class="form-field">向量维度<input v-model.number="form.embeddingDimensions" required type="number" min="64" max="2048" step="1"></label><label class="form-field address-field-wide">向量API Key<input v-model="embeddingKey" type="password" autocomplete="new-password" maxlength="500" :disabled="form.reuseChatKey" :placeholder="selected?.hasEmbeddingKey ? '已配置，留空保留' : '可使用独立Key'"></label><label class="checkbox-field"><input v-model="form.reuseChatKey" type="checkbox">复制生成Key到新草稿的向量配置</label><label class="checkbox-field"><input v-model="form.clearEmbeddingKey" type="checkbox" :disabled="form.reuseChatKey">明确清除新草稿的向量Key</label><label class="form-field address-field-wide">客服提示词模板<textarea v-model="form.promptTemplate" rows="6" required maxlength="6000"></textarea><span class="field-hint">允许变量：{question}、{history}、{knowledge}、{products}、{policy}。身份、只读业务及证据限制由系统固定加入。</span></label></div>
          <details class="model-parameters"><summary>生成参数、超时与调用限额</summary><div class="address-fields"><label v-for="parameter in parameters" :key="parameter.key" class="form-field">{{ parameter.label }}<input v-model.number="form.parameters[parameter.key]" type="number" required :min="parameter.min" :max="parameter.max" :step="parameter.step ?? 1"></label></div></details><div class="table-actions"><button class="primary-button" :disabled="busy">{{ busy ? '正在处理…' : '保存为新版本草稿' }}</button><span class="field-hint">Key仅写入加密存储，不返回明文；此处不会存入浏览器持久存储。</span></div>
        </form>
        <section v-if="selected" class="model-tests"><h3>测试与激活 · 已保存版本 v{{ selected.id }}</h3><p class="field-hint">测试使用已保存配置，计入调用额度。当前编辑内容需先保存。</p><div class="table-actions"><button v-for="capability in ['chat', 'stream', 'intent', 'embedding']" :key="capability" type="button" class="secondary-button" :disabled="busy" @click="test(capability)">{{ capability === 'chat' ? '测试生成' : capability === 'stream' ? '测试流式输出' : capability === 'intent' ? '测试意图分类' : '测试向量' }}</button><button type="button" class="primary-button" :disabled="busy || !selected.hasChatKey || selected.active" @click="activate">激活此版本</button><button v-if="selected.active" type="button" class="secondary-button" :disabled="busy" @click="disable">关闭在线模型</button></div><p v-for="result in results" :key="result.name" :class="result.success ? 'ai-success' : 'form-message-error'">{{ result.name }} · {{ result.success ? '通过' : '失败' }} · {{ result.elapsedMs }}ms {{ result.dimensions ? ' · ' + result.dimensions + '维' : '' }} · {{ result.message }}</p></section>
        <section v-if="selected" class="model-deletion"><h3>删除配置 · v{{ selected.id }}</h3><p class="field-hint">{{ deletionReason }}</p><button type="button" class="secondary-button danger-text" :disabled="busy || loading || !deletionAllowed" @click="remove">删除此配置</button></section>
      </section>
    </div>
    <section class="editor-section"><div class="catalog-heading"><div><h2>向量索引代次</h2><p class="field-hint">完整构建并追赶有效知识后才能切换，构建失败时旧代次继续服务。</p></div><div class="table-actions"><button type="button" class="secondary-button" :disabled="busy || !selected?.active || !selected?.hasEmbeddingKey" @click="build">为当前激活配置构建向量</button><button type="button" class="text-action" :disabled="busy || loading" @click="load">刷新</button></div></div><p v-if="!profiles.length" class="muted">暂无向量代次，知识库使用关键词检索。</p><div v-else class="table-scroll"><table class="admin-table"><thead><tr><th>代次 / 配置</th><th>模型</th><th>维度</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="profile in profiles" :key="profile.id"><td>{{ profile.id }} / v{{ profile.configId }}</td><td>{{ profile.model }}</td><td>{{ profile.dimensions }}</td><td>{{ profile.status }}</td><td><div class="table-actions"><button v-if="profile.status === 'READY'" type="button" class="text-action" :disabled="busy" @click="switchTo(profile.id)">切换到此代次</button><button v-if="['BUILDING', 'READY'].includes(profile.status)" type="button" class="text-action danger-text" :disabled="busy" @click="cancel(profile.id)">取消构建</button></div></td></tr></tbody></table></div></section>
  </section>
</template>
<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import 'element-plus/es/components/message-box/style/css'
import PageStatus from '../components/PageStatus.vue'
import { errorMessage } from '../api/catalog'
import * as api from '../api/admin-ai'
const defaults: api.ModelParameters = { temperature: .2, maxOutputTokens: 1200, historyTurns: 10, connectTimeoutSeconds: 10, firstContentSeconds: 20, idleTimeoutSeconds: 15, totalTimeoutSeconds: 90, buyerPerMinute: 10, guestPerMinute: 3, buyerDaily: 100, guestDaily: 20, globalDailyCalls: 1000 }
const fresh = (): api.ModelInput => ({ name: '', chatBaseUrl: '', chatModel: 'qwen3.7-plus', clearChatKey: false, embeddingBaseUrl: '', embeddingModel: 'text-embedding-v4', clearEmbeddingKey: false, reuseChatKey: false, embeddingDimensions: 1024, promptTemplate: '你是鲜果商城客服，请简洁、友好地用中文回答。\n问题：{question}\n已完成对话：{history}\n知识依据：{knowledge}\n当前商品：{products}\n业务政策：{policy}', parameters: { ...defaults } })
const form = reactive(fresh()), models = ref<api.ModelConfig[]>([]), selected = ref<api.ModelConfig | null>(null), profiles = ref<api.Profile[]>([])
const chatKey = ref(''), embeddingKey = ref(''), loading = ref(false), error = ref(''), formError = ref(''), notice = ref(''), busy = ref(false), results = ref<api.Capability[]>([])
const deletionReason = computed(() => typeof selected.value?.deletionReason === 'string' && selected.value.deletionReason.trim() ? selected.value.deletionReason : '当前服务未返回删除规则，请更新并重启后端后刷新页面。')
const deletionAllowed = computed(() => !!selected.value && ['DELETE', 'ARCHIVE'].includes(selected.value.deletionMode ?? '') && typeof selected.value.deletionReason === 'string' && !!selected.value.deletionReason.trim())
const parameters: { key: keyof api.ModelParameters; label: string; min: number; max: number; step?: number }[] = [{ key: 'temperature', label: '温度', min: 0, max: 2, step: .01 }, { key: 'maxOutputTokens', label: '输出Token上限', min: 64, max: 4096 }, { key: 'historyTurns', label: '历史问答对', min: 0, max: 10 }, { key: 'connectTimeoutSeconds', label: '连接超时（秒）', min: 1, max: 30 }, { key: 'firstContentSeconds', label: '首内容超时（秒）', min: 2, max: 60 }, { key: 'idleTimeoutSeconds', label: '流空闲超时（秒）', min: 2, max: 60 }, { key: 'totalTimeoutSeconds', label: '整轮超时（秒）', min: 10, max: 180 }, { key: 'buyerPerMinute', label: '买家每分钟提问', min: 1, max: 60 }, { key: 'guestPerMinute', label: '访客每分钟提问', min: 1, max: 20 }, { key: 'buyerDaily', label: '买家每日提问', min: 1, max: 1000 }, { key: 'guestDaily', label: '访客每日提问', min: 1, max: 100 }, { key: 'globalDailyCalls', label: '全站每日生成调用', min: 1, max: 100000 }]
function reset() { selected.value = null; Object.assign(form, fresh(), { baseId: undefined }); chatKey.value = ''; embeddingKey.value = ''; results.value = []; formError.value = ''; notice.value = '' }
function choose(model: api.ModelConfig) { selected.value = model; Object.assign(form, { ...fresh(), baseId: model.id, name: model.name, chatBaseUrl: model.chatBaseUrl, chatModel: model.chatModel, embeddingBaseUrl: model.embeddingBaseUrl, embeddingModel: model.embeddingModel, embeddingDimensions: model.embeddingDimensions, promptTemplate: model.promptTemplate, parameters: { ...model.parameters } }); chatKey.value = ''; embeddingKey.value = ''; results.value = []; formError.value = ''; notice.value = '' }
async function load() { loading.value = true; error.value = ''; try { [models.value, profiles.value] = await Promise.all([api.listModels(), api.listProfiles()]); if (selected.value) { const current = models.value.find(m => m.id === selected.value!.id); if (current) selected.value = current; else reset() } else if (models.value[0]) choose(models.value.find(m => m.active) ?? models.value[0]) } catch (failure) { models.value = []; profiles.value = []; reset(); error.value = errorMessage(failure) } finally { loading.value = false } }
async function action(operation: () => Promise<unknown>, success: string) { busy.value = true; formError.value = ''; notice.value = ''; try { await operation(); await load(); notice.value = success } catch (failure) { formError.value = errorMessage(failure) } finally { busy.value = false } }
async function save() { await action(async () => { const created = await api.saveModel({ ...form, ...(chatKey.value ? { chatKey: chatKey.value } : {}), ...(embeddingKey.value ? { embeddingKey: embeddingKey.value } : {}) }); choose(created) }, '新草稿已保存，请测试后激活。') }
async function test(capability: string) { if (!selected.value) return; await action(async () => { const tested = await api.testModel(selected.value!.id, capability); results.value = [...results.value.filter(item => item.name !== capability), ...tested] }, '能力测试已返回结果。') }
async function activate() { if (selected.value) await action(() => api.activateModel(selected.value!.id), '此版本已激活，新请求将使用它。') }
async function disable() { if (selected.value) await action(() => api.disableModel(selected.value!.id), '在线模型已关闭，新请求使用基础咨询。') }
async function remove() {
  const model = selected.value
  if (!model || busy.value || loading.value || !deletionAllowed.value) return
  busy.value = true
  try {
    try { await ElMessageBox.confirm(`确认删除“${model.name}”（v${model.id}）？${model.deletionReason}。当前未保存的编辑也将丢弃。`, '删除模型配置', { confirmButtonText: '删除', cancelButtonText: '取消', type: 'warning' }) } catch { return }
    formError.value = ''; notice.value = ''
    const result = await api.deleteModel(model.id)
    reset(); await load()
    notice.value = result.mode === 'DELETE' ? '配置已永久删除。' : '配置已从管理列表移除，历史追溯数据保留。'
  } catch (failure) { formError.value = errorMessage(failure) }
  finally { busy.value = false }
}
async function build() { if (selected.value) await action(() => api.buildProfile(selected.value!.id), '向量构建任务已创建，请刷新查看进度。') }
async function switchTo(id: number) { await action(() => api.switchProfile(id), '新向量代次已生效。') }
async function cancel(id: number) { await action(() => api.cancelProfile(id), '构建已取消，原有效代次继续服务。') }
onMounted(load)
</script>
<style scoped>
.ai-models{max-width:1180px}.model-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:28px;margin-top:22px}.model-layout>*{min-width:0}.model-layout .field-hint{overflow-wrap:anywhere;min-width:0;white-space:normal}.model-layout>.editor-section{margin-top:0;padding-top:0;border-top:0}.model-version{display:block;width:100%;background:none;border:0;border-bottom:1px solid #e3eadf;text-align:left;padding:14px 12px;cursor:pointer;font:inherit;overflow-wrap:anywhere}.model-version strong{display:block;font-size:13px;color:#3b573d}.model-version strong span{font-size:9px;padding:3px 5px;background:#dfedda;color:#467a3d;border-radius:4px;margin-left:5px}.model-version small{display:block;font-size:10px;color:#8d9986;margin-top:6px}.model-version.selected{border-radius:6px;background:#f2f7ee}.model-parameters{margin:20px 0;font-size:12px;color:#65795e}.model-parameters summary{cursor:pointer;margin-bottom:16px}.model-deletion{margin-top:24px;padding-top:18px;border-top:1px solid #e1eadb}.model-deletion h3{font-size:15px}.model-tests{border-top:1px solid #e1eadb;margin-top:25px;padding-top:20px}.model-tests h3{font-size:15px}.ai-config-warning{padding:13px;background:#fff7e6;color:#947b43;font-size:12px;line-height:1.8}.ai-success{font-size:12px;color:#3d7b42;line-height:1.8}.table-actions{flex-wrap:wrap;gap:10px}@media(max-width:850px){.model-layout{grid-template-columns:minmax(0,1fr);gap:24px}.model-layout>aside{display:flex;overflow-x:auto;gap:10px;max-height:160px}.model-version{flex:0 0 220px;border:1px solid #e3eadf;border-radius:5px}}
</style>
